    private const string AdapterPart01 =
        """
        // <auto-generated />
        // {{WORKER_PLATFORM_IMPORTS_START}}
        import { EmailMessage } from 'cloudflare:email';
        import { connect } from 'cloudflare:sockets';
        // {{WORKER_PLATFORM_IMPORTS_END}}
        import { dotnet } from './_framework/dotnet.js';
        import { config as bootConfig } from './_framework/dotnet.boot.js';
        {{WORKER_BOOT_RESOURCE_IMPORTS}}

        bootConfig.disableNoCacheFetch = true;
        bootConfig.resources.wasmSymbols = [];
        {{WORKER_BOOT_RESOURCE_MAP}}

        const invocations = new Map();
        // {{WORKER_PLATFORM_STATE_START}}
        const digestStreams = new Map();
        const containerExecProcesses = new Map();
        const durableSqlCursors = new Map();
        const durableTransactions = new Map();
        const rpcStubs = new Map();
        const tcpSockets = new Map();
        const webSockets = new Map();
        const webSocketHandles = new WeakMap();
        let nextDigestStreamId = 0;
        let nextContainerExecProcessId = 0;
        let nextDurableSqlCursorId = 0;
        let nextTcpSocketId = 0;
        let nextWebSocketId = 0;
        let nextEmailMessageId = 0;
        let nextAbortControllerId = 0;
        let nextDurableTransactionId = 0;
        let nextRpcStubId = 0;
        let managedRuntime = null;
        let managedHost = null;
        // {{WORKER_PLATFORM_STATE_END}}
        let nextInvocationId = 0;
        let nextNativeRequestId = 0;
        let nextNativeResponseId = 0;

        function installWorkerTimers() {
          if (!globalThis.scheduler || typeof globalThis.scheduler.wait !== 'function') {
            return;
          }

          let nextTimerId = 1;
          const timers = new Map();

          globalThis.setTimeout = (callback, delay = 0, ...args) => {
            const id = nextTimerId++;
            const timer = { cancelled: false };
            timers.set(id, timer);

            globalThis.scheduler.wait(Number(delay) || 0).then(() => {
              if (timer.cancelled) {
                return;
              }

              timers.delete(id);
              callback(...args);
            });

            return id;
          };

          globalThis.clearTimeout = id => {
            const timer = timers.get(id);
            if (timer) {
              timer.cancelled = true;
              timers.delete(id);
            }
          };
        }

        async function runManagedInvocation(runtime, pump, start, poll) {
          let state = JSON.parse(start());
          let pumpTurns = 0;

          while (!state.completed) {
            pump?.();
            runtime.INTERNAL?.mono_background_exec?.();
            pumpTurns++;

            if (pumpTurns > 10000) {
              throw new Error('Managed invocation did not complete after pumping browser-wasm continuations.');
            }

            if (globalThis.scheduler && typeof globalThis.scheduler.wait === 'function') {
              await globalThis.scheduler.wait(1);
            } else {
              await Promise.resolve();
            }

            pump?.();
            runtime.INTERNAL?.mono_background_exec?.();
            state = JSON.parse(poll(state.handle));
          }

          return state.result;
        }

        export default async function createWorker(manifest) {
          installWorkerTimers();

          const loadBootResource = (type, name) => {
            if (type === 'manifest') {
              return { config: bootConfig };
            }

            if (type === 'dotnetjs') {
              return `./${name}`;
            }

            if (bootResourceModules) {
              const resource = bootResourceModules.get(name);
              if (resource === undefined) {
                throw new Error(`Unknown .NET boot resource: ${name}`);
              }

              if (type === 'dotnetwasm') {
                return {
                  ok: true,
                  compiledModule: resource
                };
              }

              return new Response(resource);
            }

            {{WORKER_BOOT_RESOURCE_FALLBACK}}
          };

          const runtime = await dotnet
            .withConfig(bootConfig)
            .withResourceLoader(loadBootResource)
            .withRuntimeOptions(["--no-jiterpreter-traces-enabled"])
            .withDiagnosticTracing(false)
            .create();

          runtime.setModuleImports('dotnet.js', {
            cloudflareWorkers: {
              bindings: {
                dispatch: dispatchBinding
              }
            }
          });

          const config = runtime.getConfig();
          const host = await resolveManagedHost(runtime, config);
          // {{WORKER_PLATFORM_STATE_ASSIGNMENT_START}}
          managedRuntime = runtime;
          managedHost = host;
          // {{WORKER_PLATFORM_STATE_ASSIGNMENT_END}}
          await runtime.runMain(config.mainAssemblyName, []);

          return {
            // {{WORKER_FETCH_HANDLER_START}}
            async fetch(request, env, ctx) {
              const invocationId = retainInvocation(env, ctx);
              const requestEnvelope = await toRequestEnvelope(invocationId, request);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  request: requestEnvelope,
                  environment: toEnvironmentEnvelope(invocationId, env),
                  context: toContextEnvelope(ctx)
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.fetchStart(payloadJson),
                  handle => host.fetchPoll(handle));
                registerContextEffects(invocationId, ctx, result, host, runtime);
                return toResponseEnvelope(requiredInvocation(invocationId), result);
              } finally {
                releaseInvocation(invocationId);
              }
            },
            // {{WORKER_FETCH_HANDLER_END}}

            // {{WORKER_SCHEDULED_HANDLER_START}}
            async scheduled(event, env, ctx) {
              const invocationId = retainInvocation(env, ctx);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  environment: toEnvironmentEnvelope(invocationId, env),
                  context: toContextEnvelope(ctx),
                  event: {
                    cron: event.cron,
                    type: event.type ?? 'scheduled',
                    scheduledTime: new Date(event.scheduledTime).toISOString()
                  }
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.scheduledStart(payloadJson),
                  handle => host.poll(handle));
                registerContextEffects(invocationId, ctx, result, host, runtime);
              } finally {
                releaseInvocation(invocationId);
              }
            },
            // {{WORKER_SCHEDULED_HANDLER_END}}

            // {{WORKER_QUEUE_HANDLER_START}}
            async queue(batch, env, ctx) {
              const invocationId = retainInvocation(env, ctx);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  environment: toEnvironmentEnvelope(invocationId, env),
                  context: toContextEnvelope(ctx),
                  batch: {
                    queue: batch.queue ?? '',
                    messages: batch.messages.map(toQueueMessageEnvelope)
                  }
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.queueStart(payloadJson),
                  handle => host.poll(handle));
                applyQueueDispositions(batch, result);
                registerContextEffects(invocationId, ctx, result, host, runtime);
              } finally {
                releaseInvocation(invocationId);
              }
            },
            // {{WORKER_QUEUE_HANDLER_END}}

            // {{WORKER_EMAIL_HANDLER_START}}
            async email(message, env, ctx) {
              const invocationId = retainInvocation(env, ctx);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  environment: toEnvironmentEnvelope(invocationId, env),
                  context: toContextEnvelope(ctx),
                  message: toEmailMessageEnvelope(invocationId, message)
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.emailStart(payloadJson),
                  handle => host.poll(handle));
                registerContextEffects(invocationId, ctx, result, host, runtime);
              } finally {
                releaseInvocation(invocationId);
              }
            },
            // {{WORKER_EMAIL_HANDLER_END}}

            // {{WORKER_TAIL_HANDLER_START}}
            async tail(events, env, ctx) {
              const invocationId = retainInvocation(env, ctx);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  environment: toEnvironmentEnvelope(invocationId, env),
                  context: toContextEnvelope(ctx),
                  event: tailEventEnvelope(events)
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.tailStart(payloadJson),
                  handle => host.poll(handle));
                registerContextEffects(invocationId, ctx, result, host, runtime);
              } finally {
                releaseInvocation(invocationId);
              }
            },
            // {{WORKER_TAIL_HANDLER_END}}

            // {{WORKER_DURABLE_OBJECT_HANDLERS_START}}
            async durableObjectFetch(exportName, state, request, env) {
              const invocationId = retainInvocation(env, null, state);
              const requestEnvelope = await toRequestEnvelope(invocationId, request);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  exportName,
                  durableObjectId: durableObjectId(state),
                  request: requestEnvelope,
                  environment: toEnvironmentEnvelope(invocationId, env)
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.durableObjectFetchStart(payloadJson),
                  handle => host.poll(handle));
                return toResponseEnvelope(requiredInvocation(invocationId), result);
              } finally {
                releaseInvocation(invocationId);
              }
            },

            async durableObjectAlarm(exportName, state, env, alarmInfo) {
              const invocationId = retainInvocation(env, null, state);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  exportName,
                  durableObjectId: durableObjectId(state),
                  environment: toEnvironmentEnvelope(invocationId, env),
                  alarmInfo: alarmInfo == null ? null : {
                    retryCount: alarmInfo.retryCount ?? 0,
                    isRetry: alarmInfo.isRetry === true
                  }
                });
                await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.durableObjectAlarmStart(payloadJson),
                  handle => host.poll(handle));
              } finally {
                releaseInvocation(invocationId);
              }
            },

            async durableObjectRpc(exportName, methodName, state, env, args) {
              const invocationId = retainInvocation(env, null, state);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  exportName,
                  methodName,
                  durableObjectId: durableObjectId(state),
                  environment: toEnvironmentEnvelope(invocationId, env),
                  arguments: toManagedRpcArguments(args)
                });
                const result = await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.durableObjectRpcStart(payloadJson),
                  handle => host.poll(handle));
                const envelope = typeof result === 'string' ? JSON.parse(result) : result;
                return managedRpcReturnValue(envelope, host);
              } finally {
                releaseInvocation(invocationId);
              }
            },

            async durableObjectWebSocketMessage(exportName, state, ws, message, env) {
              const invocationId = retainInvocation(env, null, state);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  exportName,
                  durableObjectId: durableObjectId(state),
                  environment: toEnvironmentEnvelope(invocationId, env),
                  webSocketHandle: retainWebSocket(ws, false),
                  message: await toWebSocketMessageEnvelope(message)
                });
                await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.durableObjectWebSocketMessageStart(payloadJson),
                  handle => host.poll(handle));
              } finally {
                releaseInvocation(invocationId);
              }
            },

            async durableObjectWebSocketClose(exportName, state, ws, code, reason, wasClean, env) {
              const invocationId = retainInvocation(env, null, state);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  exportName,
                  durableObjectId: durableObjectId(state),
                  environment: toEnvironmentEnvelope(invocationId, env),
                  webSocketHandle: retainWebSocket(ws, false),
                  code,
                  reason: reason ?? '',
                  wasClean: wasClean === true
                });
                await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.durableObjectWebSocketCloseStart(payloadJson),
                  handle => host.poll(handle));
              } finally {
                releaseInvocation(invocationId);
              }
            },

            async durableObjectWebSocketError(exportName, state, ws, error, env) {
              const invocationId = retainInvocation(env, null, state);
              try {
                const payloadJson = JSON.stringify({
                  manifest,
                  exportName,
                  durableObjectId: durableObjectId(state),
                  environment: toEnvironmentEnvelope(invocationId, env),
                  webSocketHandle: retainWebSocket(ws, false),
                  error: {
                    message: error instanceof Error ? error.message : String(error)
                  }
                });
                await runManagedInvocation(
                  runtime,
                  host.pumpContinuations,
                  () => host.durableObjectWebSocketErrorStart(payloadJson),
                  handle => host.poll(handle));
              } finally {
                releaseInvocation(invocationId);
              }
            }
            // {{WORKER_DURABLE_OBJECT_HANDLERS_END}}
          };
        }

        async function toRequestEnvelope(invocationId, request) {
          return {
            url: request.url,
            method: request.method,
            headers: headersEnvelope(request.headers),
            bodyBase64: null,
            nativeRequestHandle: retainNativeRequest(invocationId, request),
            cf: request.cf ?? null
          };
        }

        function toResponseEnvelope(invocation, value) {
          const envelope = typeof value === 'string' ? JSON.parse(value) : value;
          const headers = new Headers();

          for (const header of envelope.headers ?? []) {
            headers.append(header.name, header.value);
          }

          const body = envelope.bodyBase64 == null
            ? null
            : fromBase64(envelope.bodyBase64);

          // {{WORKER_PLATFORM_RESPONSE_WEBSOCKET_START}}
          if (envelope.webSocketHandle != null) {
            const entry = webSockets.get(envelope.webSocketHandle);
            if (entry == null) {
              throw new Error(`WebSocket handle '${envelope.webSocketHandle}' is not defined.`);
            }

            releaseWebSocket(envelope.webSocketHandle);
            return new Response(null, {
              status: 101,
              webSocket: entry.socket
            });
          }
          // {{WORKER_PLATFORM_RESPONSE_WEBSOCKET_END}}

          const init = {
            status: envelope.status,
            headers
          };

          if (envelope.statusText != null) {
            init.statusText = envelope.statusText;
          }

          if (envelope.cf != null) {
            init.cf = envelope.cf;
          }

          if (envelope.encodeBody != null) {
            init.encodeBody = envelope.encodeBody;
          }

          if (envelope.nativeResponseHandle != null) {
            const response = nativeResponse(invocation, envelope.nativeResponseHandle);
            releaseNativeResponse(invocation, envelope.nativeResponseHandle);
            return new Response(response.body, init);
          }

          if (envelope.nativeBodyStreamSource != null && envelope.nativeBodyStreamHandle != null) {
            return new Response(nativeBodyStream(invocation, envelope.nativeBodyStreamSource, envelope.nativeBodyStreamHandle), init);
          }

          if (envelope.managedBodyStreamHandle != null) {
            return new Response(createManagedReadableStream(invocation, envelope.managedBodyStreamHandle), init);
          }

          return new Response(body, init);
        }

        function registerContextEffects(invocationId, ctx, value, host, runtime) {
          const envelope = typeof value === 'string' ? JSON.parse(value) : value;
          if (envelope.passThroughOnException === true && ctx?.passThroughOnException != null) {
            ctx.passThroughOnException();
          }

          for (const handle of envelope.waitUntilHandles ?? []) {
            retainInvocationRef(invocationId);
            const promise = runManagedInvocation(
              runtime,
              host.pumpContinuations,
              () => host.waitUntilStart(handle),
              value => host.poll(value))
              .finally(() => releaseInvocation(invocationId));
            if (ctx?.waitUntil != null) {
              ctx.waitUntil(promise);
            } else {
              promise.catch(() => {});
            }
          }
        }

        // {{WORKER_QUEUE_DISPOSITIONS_START}}
        function applyQueueDispositions(batch, value) {
          const envelope = typeof value === 'string' ? JSON.parse(value) : value;
          for (const disposition of envelope.queueDispositions ?? []) {
            const message = batch.messages[disposition.index];
            if (message == null) {
              throw new Error(`Queue message index '${disposition.index}' is not defined.`);
            }

            switch (disposition.kind) {
              case 'ack':
                message.ack();
                break;
              case 'retry':
                message.retry(queueRetryOptions(disposition.options));
                break;
              default:
                throw new Error(`Unsupported queue disposition '${disposition.kind}'.`);
            }
          }
        }
        // {{WORKER_QUEUE_DISPOSITIONS_END}}

        function toEnvironmentEnvelope(invocationId, env) {
          const bindings = {};

          for (const [name, value] of Object.entries(env ?? {})) {
            if (isJsonBindingValue(value)) {
              bindings[name] = cloneJsonBindingValue(value);
            }
          }

          return { invocationId, bindings };
        }

        function isJsonBindingValue(value, seen = new Set()) {
          if (value == null) {
            return true;
          }

          switch (typeof value) {
            case 'string':
            case 'boolean':
              return true;
            case 'number':
              return Number.isFinite(value);
            case 'object':
              break;
            default:
              return false;
          }

          if (seen.has(value)) {
            return false;
          }
          seen.add(value);

          if (Array.isArray(value)) {
            return value.every(item => isJsonBindingValue(item, seen));
          }

          const prototype = Object.getPrototypeOf(value);
          if (prototype !== Object.prototype && prototype !== null) {
            return false;
          }

          return Object.values(value).every(item => isJsonBindingValue(item, seen));
        }

        function cloneJsonBindingValue(value) {
          if (value == null || ['string', 'number', 'boolean'].includes(typeof value)) {
            return value;
          }

          return JSON.parse(JSON.stringify(value));
        }

        function toContextEnvelope(ctx) {
          return {
            props: ctx?.props ?? null
          };
        }

        // {{WORKER_TAIL_HELPERS_START}}
        function tailEventEnvelope(events) {
          return {
            type: events?.type ?? 'tail',
            traces: (Array.isArray(events) ? events : events?.traces ?? []).map(tailItemEnvelope)
          };
        }

        function tailItemEnvelope(item) {
          return {
            scriptName: item?.scriptName ?? '',
            event: tailFetchEventEnvelope(item?.event),
            eventTimestamp: toIsoTimestamp(item?.eventTimestamp),
            logs: (item?.logs ?? []).map(tailLogEnvelope),
            exceptions: (item?.exceptions ?? []).map(tailExceptionEnvelope),
            outcome: item?.outcome ?? 'unknown'
          };
        }

        function tailFetchEventEnvelope(event) {
          if (event == null) {
            return null;
          }

          return {
            request: tailRequestEnvelope(event.request),
            response: {
              status: event.response?.status ?? 0
            }
          };
        }

        function tailRequestEnvelope(request) {
          return {
            cf: request?.cf ?? null,
            headers: request?.headers ?? {},
            method: request?.method ?? '',
            url: request?.url ?? ''
          };
        }

        function tailLogEnvelope(log) {
          return {
            timestamp: toIsoTimestamp(log?.timestamp),
            level: log?.level ?? '',
            message: log?.message ?? []
          };
        }

        function tailExceptionEnvelope(exception) {
          return {
            timestamp: toIsoTimestamp(exception?.timestamp),
            name: exception?.name ?? '',
            message: exception?.message ?? null
          };
        }
        function toIsoTimestamp(value) {
          if (value == null) {
            return new Date(0).toISOString();
        """;
}
